// Generated by vite at startup. Disk content is overwritten on each
// vite boot so vitest (which does not run vite) sees the most recent
// values. The file exists in git for vitest's import resolution.
export const FRONTEND_DISPLAY = "0.0.0+dev";
export const FRONTEND_LONG_SHA = "dev";
export const FRONTEND_COMMIT_DATE: string | null = null;
